import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from roman import to_roman, from_roman


# ---- obviously-correct reference model ----
_TH = ["", "M", "MM", "MMM"]
_H = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
_T = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
_O = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]

def ref_to_roman(n: int) -> str:
    return _TH[n // 1000] + _H[(n % 1000) // 100] + _T[(n % 100) // 10] + _O[n % 10]


# ---- examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_58():
    assert from_roman("LVIII") == 58

def test_example_from_roman_IIII_raises():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_raises():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- to_roman reference equivalence ----
@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_to_from(n):
    assert from_roman(to_roman(n)) == n

def test_roundtrip_exhaustive_spot():
    # spot-check boundaries + a sweep; deterministic
    for n in list(range(1, 110)) + [399, 400, 401, 499, 500, 899, 900, 999,
                                    1000, 1994, 3888, 3990, 3999]:
        assert from_roman(to_roman(n)) == n
        assert to_roman(n) == ref_to_roman(n)

def test_to_roman_results_are_canonical_roundtrip():
    for n in range(1, 4000):
        s = to_roman(n)
        assert isinstance(s, str)
        assert s == s.upper()
        assert to_roman(from_roman(s)) == s


# ---- to_roman domain errors ----
@given(st.integers().filter(lambda x: x < 1 or x > 3999))
def test_to_roman_out_of_range_raises_valueerror(n):
    # exclude bools: bool is handled by TypeError test; hypothesis ints never give bool
    with pytest.raises(ValueError):
        to_roman(n)

def test_to_roman_boundaries_reject():
    for bad in [0, -1, -100, -3999, 4000, 4001, 5000, 10000, -2**31, 2**31]:
        with pytest.raises(ValueError):
            to_roman(bad)

def test_to_roman_accepts_boundaries():
    assert to_roman(1) == "I"
    assert to_roman(3999) == "MMMCMXCIX"

def test_to_roman_type_rejects():
    bads = [True, False, 1.0, 4.0, "IV", "4", None, [4], (4,), 4.5, float("nan")]
    for b in bads:
        with pytest.raises(TypeError):
            to_roman(b)  # type: ignore


# ---- from_roman type errors ----
def test_from_roman_type_rejects():
    bads = [True, False, None, 123, 4.5, b"IV", ["X"], ("X",), 0]
    for b in bads:
        with pytest.raises(TypeError):
            from_roman(b)  # type: ignore


# ---- from_roman strictness: explicit non-canonical ----
def test_from_roman_rejects_explicit_bad():
    bads = [
        "", "iv", "Iv", "IV ", " X", "X\n", "X\nX", "\tX", "X ",
        "IIII", "VV", "LL", "DD", "IIV", "IXI", "IVI", "IXIV",
        "IC", "IM", "XM", "VM", "LM", "DM", "IL", "XD", "VX", "LC",
        "MMMM", "MMMMM", "MMMMMMMMMM", "CCCC", "XXXX", "VVV",
        "IXX", "IVX", "CMM", "IXIX", "IVIV", "VIV", "IIX",
        "MIM", "DCD", "LXL", "XCXC", "CMCM",
        "A", "Z", "iv", "MMMMCMXCIX", "?", "-", "M M",
        "MCMXCIVA", "MM M", "N", "IIIIIIIII",
    ]
    for s in bads:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_above_3999():
    for s in ["MMMM", "MMMMM", "MMMMCMXCIX", "MMMMMMMMMM", "MMMMDCCCLXXXVIII"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_empty_and_whitespace():
    for s in ["", " ", "  ", "\n", "\t", " X", "X ", "X\n", " I V"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_lowercase():
    for s in ["iv", "ix", "xl", "mcmxciv", "lviii", "i", "v", "m"]:
        with pytest.raises(ValueError):
            from_roman(s)


# ---- from_roman invariants ----
@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_in_range(n):
    v = from_roman(to_roman(n))
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999

@given(st.integers(min_value=1, max_value=3999))
def test_to_from_inverse_second_direction(n):
    s = to_roman(n)
    assert to_roman(from_roman(s)) == s

@given(st.text(alphabet="IVXLCDMivxlcdm \t\nXYZ012", min_size=0, max_size=12))
def test_from_roman_accept_iff_canonical(s):
    try:
        v = from_roman(s)
    except (ValueError, TypeError):
        # every canonical string must be accepted, so rejected strings
        # must not equal any canonical form
        for n in range(1, 4000):
            assert s != ref_to_roman(n)
    else:
        assert isinstance(v, int) and 1 <= v <= 3999
        assert to_roman(v) == s
        assert ref_to_roman(v) == s

@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=8))
def test_random_over_alphabet_either_rejects_or_roundtrips(s):
    try:
        v = from_roman(s)
    except ValueError:
        pass
    else:
        assert to_roman(v) == s


# ---- suspicious palindrome-continuation backdoor ----
def test_palindrome_suffix_trick_rejected():
    # If an implementation continued parsing when the remainder equals
    # the reverse of the consumed prefix, it would wrongly accept
    # P + reverse(P). All such strings are non-canonical and must fail.
    pals = []
    for n in [3888, 3887, 3777, 2888, 3333, 2999, 3999, 1888, 2777]:
        p = ref_to_roman(n)
        if len(p) >= 10:
            pals.append(p + p[::-1])
    # also hand-built long palindromic shapes
    pals += ["MMMDCCCLXXXVIII" + "MMMDCCCLXXXVIII"[::-1],
             "MMDCCCLXXXVIII" + "MMDCCCLXXXVIII"[::-1]]
    assert len(pals) > 0
    for s in pals:
        # sanity: these are not canonical
        assert s not in {ref_to_roman(i) for i in range(1, 4000)}
        with pytest.raises(ValueError):
            from_roman(s)

@given(st.integers(min_value=1, max_value=3999))
def test_long_canonical_plus_reverse_rejected(n):
    p = ref_to_roman(n)
    assume(len(p) >= 6)
    s = p + p[::-1]
    # s is canonical only if it happens to equal some to_roman(m);
    # otherwise must raise. Check spec directly:
    is_canonical = any(s == ref_to_roman(m) for m in range(1, 4000))
    if not is_canonical:
        with pytest.raises(ValueError):
            from_roman(s)
    else:
        assert to_roman(from_roman(s)) == s
